import { existsSync, readFileSync } from 'node:fs'
import { gunzipSync } from 'node:zlib'
import { expect, it, vi } from 'vitest'
import { unpackHeights } from '../src/world/heightPacking'
import { loadWorld, type TerrainManifest } from '../src/world/loadWorld'

const bytes = (buffer: Buffer): ArrayBuffer =>
  buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength) as ArrayBuffer

it.each([
  {
    coarse: true,
    // Generated by pack_heights with [0, 1/8192, 8, -1/8192, 1.125, -0, 0.1, 6, 9].
    raw: '000000000000003900000041000000b90000903f00000080cdcccc3d0000c04000001041',
    packed: '00000100008000000041ffff00240080000000800080cdcccc3d00800000c040008000001041',
  },
  {
    coarse: false,
    // Generated with [100, 101, 103, 98, 65535, 700, 98, 101, 102], including a detail hole.
    raw: '6400650067006200ffffbc02620065006600',
    packed: '640001000200feff0080ffff0080bc0200000080650000806600',
  },
])('round-trips a Python-generated grid (coarse: $coarse)', ({ coarse, raw, packed }) => {
  const stream = bytes(Buffer.from(packed, 'hex'))
  expect(Buffer.from(unpackHeights(stream, 3, 3, coarse)).toString('hex')).toBe(raw)
  expect(() => unpackHeights(stream.slice(0, -1), 3, 3, coarse)).toThrow('Truncated')
})

const DATA = 'public/data/'
const manifest: TerrainManifest | undefined = existsSync(DATA + 'terrain.json')
  ? JSON.parse(readFileSync(DATA + 'terrain.json', 'utf8'))
  : undefined

it.runIf(Boolean(manifest && existsSync(DATA + 'features.json')))('loads the legacy Apex grids', async () => {
  const legacy = structuredClone(manifest!)
  delete legacy.packedHeights
  if (legacy.detail) delete legacy.detail.packedHeights
  const { world } = await loadFromDisk(legacy)
  expect(world.grid.columns).toBe(legacy.columns)
  expect(world.grid.detail?.columns).toBe(legacy.detail?.columns)
  expect(world.featureSource).toBe('osm-export')
})

const coarse = manifest?.packedHeights
const detail = manifest?.detail
it.runIf(Boolean(coarse && detail?.packedHeights && existsSync(DATA + coarse.file) &&
  existsSync(DATA + detail.packedHeights.file)))('loads the packed Apex grids byte for byte and falls back if unavailable', async () => {
  const grids = [
    { grid: manifest!, packed: coarse!.file, raw: 'heights.f32', coarse: true },
    { grid: detail!, packed: detail!.packedHeights!.file, raw: detail!.file, coarse: false },
  ]
  for (const { grid, packed, raw, coarse } of grids) {
    const decoded = unpackHeights(bytes(gunzipSync(readFileSync(DATA + packed))), grid.columns, grid.rows, coarse)
    expect(Buffer.from(decoded).equals(readFileSync(DATA + raw))).toBe(true)
  }

  const loaded = await loadFromDisk(manifest!)
  expect(loaded.requests).toEqual(expect.arrayContaining(grids.map(({ packed }) => packed)))
  for (const { raw } of grids) expect(loaded.requests).not.toContain(raw)

  const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})
  try {
    const fallback = await loadFromDisk(manifest!, { failPacked: true })
    expect(fallback.requests).toEqual(expect.arrayContaining(grids.map(({ raw }) => raw)))
    expect(warn).toHaveBeenCalledTimes(2)
    expect(loaded.world.grid.sampleTerrain(500, 500)).toEqual(fallback.world.grid.sampleTerrain(500, 500))
    expect(loaded.world.course.spawn).toEqual(fallback.world.course.spawn)
    expect(loaded.world.grid.detail?.columns).toBe(detail!.columns)

    const unsupported = await loadFromDisk(manifest!, { gzipSupported: false })
    expect(unsupported.requests).toEqual(expect.arrayContaining(grids.map(({ raw }) => raw)))
    for (const { packed } of grids) expect(unsupported.requests).not.toContain(packed)
  } finally {
    warn.mockRestore()
  }
})

async function loadFromDisk(
  metadata: TerrainManifest,
  { failPacked = false, gzipSupported = true } = {},
) {
  if (!gzipSupported) vi.stubGlobal('DecompressionStream', undefined)
  const requests: string[] = []
  vi.stubGlobal('fetch', async (file: string, init?: RequestInit) => {
    requests.push(file)
    if (file === 'terrain.json') return Response.json(metadata)
    if (failPacked && (file === metadata.packedHeights?.file || file === metadata.detail?.packedHeights?.file)) return new Response('invalid gzip')
    if (!existsSync(DATA + file)) return new Response(null, { status: 404 })
    return new Response(init?.method === 'HEAD' ? null : bytes(readFileSync(DATA + file)))
  })
  try {
    return { world: await loadWorld(''), requests }
  } finally {
    vi.unstubAllGlobals()
  }
}

const horizonMeta = existsSync(DATA + 'horizon.json') ? JSON.parse(readFileSync(DATA + 'horizon.json', 'utf8')) : undefined
it.runIf(Boolean(manifest?.canopy?.packed && horizonMeta?.packedHeights && horizonMeta?.packedCanopy &&
  existsSync(DATA + 'features.json')))('loads the gzip canopy and packed horizon like the raw files', async () => {
  const packed = await loadFromDisk(manifest!)
  const raw = await loadFromDisk(manifest!, { gzipSupported: false })
  const { coverFile, heightFile } = manifest!.canopy!.packed!
  expect(packed.requests).toEqual(expect.arrayContaining([coverFile, heightFile, horizonMeta.packedHeights.file, horizonMeta.packedCanopy.file]))
  expect(packed.requests).not.toContain(manifest!.canopy!.coverFile)
  expect(packed.requests).not.toContain(horizonMeta.heightFile)
  expect(raw.requests).toContain(horizonMeta.heightFile)
  const same = (a: ArrayBufferView, b: ArrayBufferView) =>
    Buffer.from(a.buffer, a.byteOffset, a.byteLength).equals(Buffer.from(b.buffer, b.byteOffset, b.byteLength))
  expect(same(packed.world.canopy!.cover, raw.world.canopy!.cover)).toBe(true)
  expect(same(packed.world.canopy!.height, raw.world.canopy!.height)).toBe(true)
  expect(same(packed.world.horizon!.heights, raw.world.horizon!.heights)).toBe(true)
  expect(same(packed.world.horizon!.canopy!, raw.world.horizon!.canopy!)).toBe(true)
})
